def _atlas_extra_model_config(selection, reasoning=None):
    """Return a validated Phase 2 model configuration without exposing secrets."""
    key = str(selection or "").strip().lower()
    cfg = ATLAS_EXTRA_CHAT_MODELS.get(key)
    if not cfg:
        return None
    default_reasoning = "on" if key == "atlas_41_flash" else ("medium" if key == "atlas_3_ultra" else "low")
    value = str(reasoning or default_reasoning).strip().lower()
    if value not in cfg["reasoning_values"]:
        value = default_reasoning
    return {
        "selection": key,
        "display_name": cfg["display_name"],
        "model_id": cfg["model_id"],
        "api_key": cfg["api_key"],
        "provider": cfg.get("provider", "nvidia"),
        "reasoning": value,
        "thinking_enabled": (key == "atlas_35_super" and value == "high"),
    }


def _atlas_extra_model_request_options(config):
    """Return the documented NVIDIA request fields for the selected Atlas model."""
    if not isinstance(config, dict):
        return {}
    if config.get("selection") == "atlas_3_ultra":
        # NVIDIA's hosted Nemotron 3 Ultra endpoint controls reasoning via
        # chat_template_kwargs: disabled, medium_effort, or full thinking.
        effort = str(config.get("reasoning") or "medium").strip().lower()
        if effort == "none":
            return {"chat_template_kwargs": {"enable_thinking": False}}
        if effort == "medium":
            return {"chat_template_kwargs": {"enable_thinking": True, "medium_effort": True}}
        return {"chat_template_kwargs": {"enable_thinking": True}}
    if config.get("selection") == "atlas_30":
        # NVIDIA's Mistral Large 4 endpoint supports low/medium/high effort.
        # Atlas defaults to low to reduce latency; reasoning remains provider-side
        # and is never streamed into the visible assistant answer.
        effort = str(config.get("reasoning") or "low").strip().lower()
        if effort not in {"low", "medium", "high"}:
            effort = "low"
        return {"reasoning_effort": effort}
    return {"chat_template_kwargs": {"enable_thinking": bool(config.get("thinking_enabled"))}}


