# ---------------------------- Small utilities ----------------------------

def esc(v: object) -> str:
    return html.escape(str(v or ""), quote=True)


def rgb(s: str, fallback: str = "FFFFFF") -> RGBColor:
    s = str(s or fallback).replace("#", "").upper()
    if not re.fullmatch(r"[0-9A-F]{6}", s):
        s = fallback
    return RGBColor.from_string(s)


def rgb_hex(s: str) -> tuple[int, int, int]:
    v = str(s or "0B0D10").replace("#", "").upper()
    if not re.fullmatch(r"[0-9A-F]{6}", v):
        v = "0B0D10"
    return tuple(int(v[i:i+2], 16) for i in (0, 2, 4))


def json_extract(text: str) -> dict:
    """Extract one JSON object even if Agnes adds markdown or surrounding prose."""
    text = (text or "").strip()
    text = re.sub(r"^```(?:json)?\s*", "", text, flags=re.I)
    text = re.sub(r"\s*```$", "", text)
    try:
        value = json.loads(text)
        if not isinstance(value, dict):
            raise ValueError("Agnes returned JSON, but it was not a JSON object.")
        return value
    except (json.JSONDecodeError, ValueError):
        decoder = json.JSONDecoder()
        for i, ch in enumerate(text):
            if ch != "{":
                continue
            try:
                value, _ = decoder.raw_decode(text[i:])
                if isinstance(value, dict):
                    return value
            except json.JSONDecodeError:
                continue
        raise ValueError("Agnes did not return valid presentation JSON.")


def slug(text: str) -> str:
    x = re.sub(r"[^a-zA-Z0-9]+", "-", text.strip().lower()).strip("-")
    return x[:60] or "presentation"


def get_json(url: str, timeout: int = 20) -> dict:
    req = Request(url, headers={"User-Agent": "Atlas-Presentation-Test/1.0"})
    with urlopen(req, timeout=timeout) as r:
        return json.loads(r.read().decode("utf-8", errors="replace"))



def deterministic_choice(seed: str, items: list[str]) -> str:
    h = hashlib.sha256(seed.encode("utf-8")).hexdigest()
    return items[int(h[:8], 16) % len(items)]


def _hex_luminance(h: str) -> float:
    r, g, b = rgb_hex(h)
    vals = []
    for c in (r, g, b):
        c = c / 255.0
        vals.append(c / 12.92 if c <= 0.03928 else ((c + 0.055) / 1.055) ** 2.4)
    return 0.2126 * vals[0] + 0.7152 * vals[1] + 0.0722 * vals[2]


def _contrast_ratio(a: str, b: str) -> float:
    la, lb = _hex_luminance(a), _hex_luminance(b)
    hi, lo = max(la, lb), min(la, lb)
    return (hi + 0.05) / (lo + 0.05)


def theme_for(topic: str, style: str = "auto", seed: str = "") -> dict:
    """Choose a fresh topic-aware palette. Auto mode varies by generation seed."""
    s = (style or "auto").lower()
    mapping = {
        "cinematic": ["obsidian_ember", "deep_ocean", "burgundy_night"],
        "luxury": ["sand_coral", "editorial_paper", "burgundy_night"],
        "editorial": ["editorial_paper", "lavender_ink", "sand_coral"],
        "corporate": ["arctic_blue", "sunlit_blue", "deep_ocean"],
        "futuristic": ["midnight_cyan", "lavender_ink", "deep_ocean"],
        "minimal": ["editorial_paper", "arctic_blue", "sage_ceramic"],
        "nature": ["forest_moss", "sage_ceramic", "deep_ocean"],
        "royal": ["royal_ultraviolet", "lavender_ink", "burgundy_night"],
    }
    topic_l = topic.lower()
    families = mapping.get(s)
    if families is None:
        if any(k in topic_l for k in ["forest", "climate", "nature", "ecology", "ocean", "earth", "wildlife"]):
            families = ["forest_moss", "sage_ceramic", "deep_ocean"]
        elif any(k in topic_l for k in ["technology", "ai", "quantum", "cyber", "space", "future", "software"]):
            families = ["midnight_cyan", "arctic_blue", "lavender_ink"]
        elif any(k in topic_l for k in ["history", "king", "rome", "egypt", "literature", "museum", "ancient"]):
            families = ["sand_coral", "editorial_paper", "burgundy_night"]
        elif any(k in topic_l for k in ["finance", "business", "strategy", "economy", "market", "startup"]):
            families = ["arctic_blue", "editorial_paper", "sunlit_blue"]
        elif any(k in topic_l for k in ["football", "soccer", "sport", "madrid", "ronaldo"]):
            families = ["sunlit_blue", "deep_ocean", "editorial_paper", "burgundy_night"]
        else:
            families = list(PALETTES)
    key = f"{topic}|{seed}|{s}"
    selected = deterministic_choice(key, families)
    return PALETTES[selected].copy()


def sanitize_theme(candidate: dict, topic: str, style: str, seed: str = "") -> dict:
    """Validate model-selected colors and reject repetitive/low-contrast themes."""
    base = theme_for(topic, style, seed)
    out = base.copy()
    if not isinstance(candidate, dict):
        return out
    for k in ("bg", "surface", "text", "muted", "accent", "accent2"):
        v = str(candidate.get(k) or "").replace("#", "").upper()
        if re.fullmatch(r"[0-9A-F]{6}", v):
            out[k] = v
    # Keep readable contrast. If the model accidentally generates a weak scheme,
    # repair only the text colors rather than discarding the whole design.
    if _contrast_ratio(out["text"], out["bg"]) < 4.5:
        out["text"] = base["text"]
    if _contrast_ratio(out["muted"], out["bg"]) < 3.0:
        out["muted"] = base["muted"]
    # Prevent the old black/orange/yellow look from becoming the de-facto theme.
    old_default = {"bg": "0B0D10", "accent": "E77A4F", "accent2": "F0C36B"}
    if all(out.get(k, "") == v for k, v in old_default.items()):
        return base
    bg_style = str(candidate.get("background_style") or "").lower() if isinstance(candidate, dict) else ""
    if bg_style in {"solid", "gradient", "split", "paper", "grid", "diagonal", "duotone", "image"}:
        out["background_style"] = bg_style
    elif bg_style == "mesh":
        out["background_style"] = "gradient"
    elif bg_style == "texture":
        out["background_style"] = "paper"
    out["dark"] = "FFFFFF" if _hex_luminance(out["bg"]) > 0.45 else "05070A"
    return out


def _merge_theme(candidate: dict | None, fallback: dict, topic: str, style: str, seed: str = "") -> dict:
    """Sanitize a slide-level theme while inheriting the deck theme for omitted fields."""
    merged = dict(fallback or {})
    if isinstance(candidate, dict):
        for key in ("bg", "surface", "text", "muted", "accent", "accent2", "background_style"):
            if key in candidate and candidate.get(key) not in (None, ""):
                merged[key] = candidate.get(key)
    safe = sanitize_theme(merged, topic, style, seed)
    if isinstance(candidate, dict) and candidate.get("background_style") in {"solid", "gradient", "split", "paper", "grid", "diagonal", "duotone", "image"}:
        safe["background_style"] = str(candidate.get("background_style"))
    elif isinstance(candidate, dict) and candidate.get("background_style") == "mesh":
        safe["background_style"] = "gradient"
    elif isinstance(candidate, dict) and candidate.get("background_style") == "texture":
        safe["background_style"] = "paper"
    return safe


def _mix_hex(a: str, b: str, amount: float) -> str:
    """Blend two RGB hex colors; amount=0 keeps a, amount=1 keeps b."""
    ar, ag, ab = rgb_hex(a)
    br, bg, bb = rgb_hex(b)
    t = max(0.0, min(1.0, float(amount)))
    return "{:02X}{:02X}{:02X}".format(
        round(ar + (br - ar) * t),
        round(ag + (bg - ag) * t),
        round(ab + (bb - ab) * t),
    )


def theme_from_image_color(base: dict, avg_color: str, topic: str, slide_index: int, seed: str = "") -> dict:
    """Create a subtle image-harmonized slide palette without sacrificing text contrast."""
    av = str(avg_color or "").replace("#", "").upper()
    if not re.fullmatch(r"[0-9A-F]{6}", av):
        return dict(base)
    # Keep the deck identity dominant while allowing each image to tint its slide.
    bg = _mix_hex(base.get("bg", "F3F0E8"), av, 0.20)
    surface = _mix_hex(base.get("surface", base.get("bg", "F3F0E8")), av, 0.16)
    accent = _mix_hex(base.get("accent", av), av, 0.42)
    accent2 = _mix_hex(base.get("accent2", accent), av, 0.20)
    candidate = dict(base)
    candidate.update({"bg": bg, "surface": surface, "accent": accent, "accent2": accent2})
    return sanitize_theme(candidate, topic, "auto", f"{seed}-image-{slide_index}")


