            _ensure_presentation_user_message(user,chat_id,topic,request_id,created_at,presentation_message_meta)
            job_payload={"topic":topic,"prompt":topic,"slides":slides,"images":images,"think":think,"text_mode":text_mode,"presentation_type":presentation_type,"audience":audience,"objective":objective,"visual_style":visual_style,"speaker_notes":speaker_notes,"chat_id":chat_id,"created_at":created_at,"request_id":request_id,"_presentation_agnes_slot":4}
            # Every explicit generation request creates a NEW durable job. Never return
